CREATE TABLE public.quizzes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title TEXT NOT NULL, description TEXT, category TEXT NOT NULL DEFAULT 'সাধারণ', difficulty TEXT NOT NULL DEFAULT 'easy', thumbnail_url TEXT, duration_seconds INTEGER NOT NULL DEFAULT 60, pass_percentage INTEGER NOT NULL DEFAULT 50, is_active BOOLEAN NOT NULL DEFAULT true, is_featured BOOLEAN NOT NULL DEFAULT false, sort_order INTEGER NOT NULL DEFAULT 0, attempt_count INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now()); ALTER TABLE public.quizzes ENABLE ROW LEVEL SECURITY; CREATE POLICY "Public read active quizzes" ON public.quizzes FOR SELECT USING (is_active = true); CREATE POLICY "Admin manage quizzes" ON public.quizzes FOR ALL USING (has_role(auth.uid(), 'admin'::app_role));